<?php require_once __DIR__.'/professional_assets/bootstrap_portal.php'; require_role(['admin']);$con->query("CREATE TABLE IF NOT EXISTS audit_log(id INT AUTO_INCREMENT PRIMARY KEY,user_name VARCHAR(120) DEFAULT '',action_name VARCHAR(150) NOT NULL,details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$con->prepare('INSERT INTO audit_log(user_name,action_name,details) VALUES(?,?,?)');$u=$_SESSION['portal_login']??'';$a=trim($_POST['action_name']);$d=trim($_POST['details']);$s->bind_param('sss',$u,$a,$d);$s->execute();$msg='Activity logged.';}$rows=$con->query('SELECT * FROM audit_log ORDER BY id DESC LIMIT 200');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"><title>Audit Log</title></head><body class="module-body"><div class="module-wrap"><div class="module-head"><div><span class="eyebrow">SECURITY</span><h1>Activity / Audit Log</h1><p>Track important administrative and clinical system actions.</p></div></div><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="panel"><h2>Log an activity</h2><form method="post" class="form-grid"><label>Action<input name="action_name" placeholder="Added medicine" required></label><label>Details<textarea name="details"></textarea></label><button class="primary-btn">Save log</button></form></div><div class="panel"><h2>Recent activity</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=esc($r['created_at'])?></td><td><?=esc($r['user_name'])?></td><td><?=esc($r['action_name'])?></td><td><?=esc($r['details'])?></td></tr><?php endwhile;?></tbody></table></div></div></div></body></html>
